import pandas as pd
import numpy as np

# Example 1: pd.Timedelta(4, 'ns') * np.array([2**62])
try:
    result = pd.Timedelta(4, 'ns') * np.array([2**62])
    probe("pd.Timedelta(4, 'ns') * np.array([2**62])", result)
except Exception as e:
    probe("pd.Timedelta(4, 'ns') * np.array([2**62])", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: pd.Timedelta(4, 'ns') * np.array([-(2**63)])
try:
    result = pd.Timedelta(4, 'ns') * np.array([-(2**63)])
    probe("pd.Timedelta(4, 'ns') * np.array([-(2**63)])", result)
except Exception as e:
